import{_ as e,o as a,a as t,b as l}from"./app.DKoEZOcr.js";const n="/ascendc.github.io/pr/5487/assets/nd2nz_new_44.BOUYAk0B.png",r="/ascendc.github.io/pr/5487/assets/nd2nz_new_2.Ce6_izUE.png",u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMD算子实现","link":"/guide/operator_practice/simd_operator_impl/simd_operator_impl"},{"text":"矩阵编程（高阶API）","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/matrix_advanced_api"},{"text":"特性场景","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/matmul_features"},{"text":"多核对齐切分","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/multi_core_aligned_split"}]},"headers":[],"relativePath":"guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/multi_core_aligned_split.md","filePath":"guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/multi_core_aligned_split.md","outlineHeaders":[{"level":2,"title":"功能介绍","slug":"功能介绍","link":"#功能介绍"},{"level":2,"title":"使用场景","slug":"使用场景","link":"#使用场景"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1787050286000}'),o={name:"guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/multi_core_aligned_split.md"};function _(p,i,s,c,m,g){return a(),t("div",null,[...i[0]||(i[0]=[l('<div><article class="markdown-body"><h1>多核对齐切分<span id="ZH-CN_TOPIC_0000002532228165"></span></h1><h2 id="功能介绍">功能介绍<span id="zh-cn_topic_0000002298767889_section16205164243819"></span><a class="header-anchor" href="#功能介绍">​</a></h2><p>为了实现多核并行，提升计算效率，需要将矩阵数据进行切分，分配到不同的核上进行处理。主要的切分策略有切分K轴和不切分K轴两种。</p><p>不切分K轴、仅切分M、N轴的策略如下：</p><ul><li>对于A矩阵，沿着M轴进行切分，切分成多份的singleCoreM，单核上处理SingleCoreM * K大小的数据。</li><li>对于B矩阵，沿着N轴进行切分，切分成多份的singleCoreN，单核上处理K * SingleCoreN大小的数据。</li><li>对于C矩阵，SingleCoreM * K大小的A矩阵和K * SingleCoreN大小的B矩阵相乘得到SingleCoreM * SingleCoreN大小的C矩阵，即为单核上输出的C矩阵大小。</li></ul><p>比如，下图中共有8个核参与计算，将A矩阵沿着M轴划分为4块，将B矩阵沿着N轴切分为两块，单核上仅处理某一分块（比如图中绿色部分为core5上参与计算的数据）：SingleCoreM * K大小的A矩阵分块和SingleCoreN * K大小的B矩阵分块相乘得到SingleCoreM * SingleCoreN大小的C矩阵分块。</p><p><img src="'+n+'" alt></p><p>切分M、N、K轴的策略如下图所示：</p><ul><li>对于A矩阵，沿着M轴进行切分，切分成多份的singleCoreM，沿着K轴切分，切分成多份的singleCoreK，单核上处理singleCoreM * singleCoreK大小的数据。</li><li>对于B矩阵，沿着K轴进行切分，切分成多份的singleCoreK，沿着N轴进行切分，切分成多份的singleCoreN，单核上处理singleCoreK * singleCoreN大小的数据。</li><li>对于C矩阵，singleCoreM * singleCoreK大小的A矩阵与singleCoreK * singleCoreN大小的B矩阵相乘并累加得到singleCoreM * singleCoreN大小的C矩阵分块。</li></ul><p>比如下图中，C矩阵中的R矩阵块，是通过A1*B1+A2*B2+A3*B3累加得到的，其中，A1*B1、A2*B2、A3*B3可在多个核上并行计算。</p><p><img src="'+r+`" alt></p><p>上述的切分策略会在Tiling参数中体现，比如SingleCoreM、SingleCoreN、SingleCoreK，开发者在host侧通过调用API自动获取Tiling参数，与单核场景的不同的是，多核Tiling需要使用<a href="../../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Tiling/Matmul_Tiling_constructor.html">MultiCoreMatmulTiling</a>构造多核Tiling对象，并通过<a href="../../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Tiling/SetDim.html">SetDim</a>接口设置Matmul计算所用的核数。注意：这里设置的核数为Matmul计算可用的核数，仅在多核场景下设置，用于计算tiling参数；SetSimdNumBlocks为整个算子计算所用核数，是实际会加载的核数，是必须设置的。SetSimdNumBlocks的设置规则请参考<a href="../../../../programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/host_tiling_implementation.html#numblocks">numBlocks的说明</a>。SetDim的设置规则如下：</p><ul><li><p>纯Cube模式（只有矩阵计算）场景，本节内容以纯Cube模式举例。</p><p><a href="../../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Tiling/SetDim.html">SetDim</a>设置当前AI处理器可用的核数，通过<a href="../../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Tiling/GetTiling.html">Tiling计算</a>得到执行Matmul计算实际使用的核数，实际使用的核数小于等于AI处理器可用的核数。SetSimdNumBlocks按照实际使用的核数由用户进行配置。</p></li><li><p>MIX模式（包含矩阵计算和矢量计算）的设置规则请参考<a href="../../fusion_operator_programming/cv_fusion/operator_impl.html#zh-cn_topic_0000001644252364_li4790115115920">MIX场景核数设置规则</a>。</p></li></ul><h2 id="使用场景">使用场景<span id="zh-cn_topic_0000002298767889_section86181999397"></span><a class="header-anchor" href="#使用场景">​</a></h2><p>多核处理Matmul矩阵计算场景。</p><h2 id="约束说明">约束说明<span id="zh-cn_topic_0000002298767889_section3388164212391"></span><a class="header-anchor" href="#约束说明">​</a></h2><p>无</p><h2 id="调用示例">调用示例<span id="zh-cn_topic_0000002298767889_section14108832203920"></span><a class="header-anchor" href="#调用示例">​</a></h2><p>该场景的关键代码示例如下。Matmul多核对齐场景的完整样例请参考：多核切M、N的样例：<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/00_introduction/02_matrix/matmul_advanced_api">Matmul多核场景的核函数（Kernel）直调样例</a>；多核切K的样例：<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/04_advanced_api/00_matmul/matmul_splitk">多核切K场景的算子样例</a>。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>// 构造多核Tiling对象
auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
matmul_tiling::MultiCoreMatmulTiling cubeTiling(*ascendcPlatform);
// 仅包含Cube计算的算子，设置可参与矩阵乘运算的核数为当前AI处理器上的Cube核数
cubeTiling.SetDim(ascendcPlatform.GetCoreNumAic());
cubeTiling.SetAType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16);
cubeTiling.SetBType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16);
cubeTiling.SetCType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);
cubeTiling.SetBiasType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);
cubeTiling.SetOrgShape(M, N, K);
cubeTiling.SetShape(M, N, K);
cubeTiling.EnableBias(isBias);
optiling::TCubeTiling tilingData;  
// 获取Tiling参数 
int ret = cubeTiling.GetTiling(tilingData);    // if ret = -1, gen tiling failed
</code></pre></div></article></div>`,1)])])}const h=e(o,[["render",_]]);export{u as __pageData,h as default};
